content.solution_code:
class MovementModule {
    constructor(speed) {
        this.speed = speed;
    }

    move() {
        return `Moving at ${this.speed} km/h.`;
    }
}

class SensorModule {
    constructor(range) {
        this.range = range;
    }

    scan() {
        return `Scanning up to ${this.range} meters.`;
    }
}

class Robot {
    constructor(name) {
        this.name = name;
        this.movementModule = null;
        this.sensorModule = null;
    }

    equipMovementModule(speed) {
        this.movementModule = new MovementModule(speed);
    }

    equipSensorModule(range) {
        this.sensorModule = new SensorModule(range);
    }

    performRoutine() {
        let output = `${this.name} is performing its routine.\n`;
        if (this.movementModule) {
            output += this.movementModule.move() + "\n";
        } else {
            output += "Movement module not equipped.\n";
        }

        if (this.sensorModule) {
            output += this.sensorModule.scan() + "\n";
        } else {
            output += "Sensor module not equipped.\n";
        }

        return output.trim();
    }

    checkSystems() {
        if (!this.movementModule) {
            return "Movement module is offline.";
        }
        if (!this.sensorModule) {
            return "Sensor module is offline.";
        }
        return "All systems nominal.";
    }
}

